-- UUID: a real column type (16 bytes), generated by the server.
-- The old way: CHAR(36) = 36 bytes per value, and you generate the id in application code.
CREATE OR REPLACE TABLE demo_uuid (
  id UUID DEFAULT UUID() PRIMARY KEY,
  note VARCHAR(50)
);

INSERT INTO demo_uuid (note) VALUES ('first'), ('second');
SELECT id, note FROM demo_uuid;

DROP TABLE demo_uuid;
